mkdir mathx && cat > mathx/mathx.go <<'E'
// Package mathx holds small integer math helpers.
package mathx

// Clamp limits v to [lo, hi].
func Clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

// Abs returns |v|.
func Abs(v int) int {
	if v < 0 {
		return -v
	}
	return v
}
E
cat > mathx/mathx_test.go <<'E'
package mathx

import "testing"

func TestClamp(t *testing.T) {
	for _, c := range [][4]int{{5, 0, 10, 5}, {-1, 0, 10, 0}, {11, 0, 10, 10}} {
		if got := Clamp(c[0], c[1], c[2]); got != c[3] {
			t.Errorf("Clamp(%d,%d,%d) = %d", c[0], c[1], c[2], got)
		}
	}
}

func TestAbs(t *testing.T) {
	if Abs(-3) != 3 || Abs(4) != 4 {
		t.Fatal("Abs")
	}
}
E
git rm -q -f util/mathx.go
sed -i '1i // Package util holds small shared helpers.' util/strings.go
python3 - <<'E'
p='util/util_test.go'
s=open(p).read()
a=s.index('func TestClamp'); b=s.index('func TestStrings')
open(p,'w').write(s[:a]+s[b:])
E
sed -i 's/util\.Clamp/mathx.Clamp/; s#"inventory/util"#"inventory/mathx"#' api/handlers.go
sed -i 's/util\.Abs/mathx.Abs/; s#"inventory/util"#"inventory/mathx"\n\t"inventory/util"#' report/report.go
gofmt -l . ; go build ./... && go test ./... 2>&1 | tail

